#!/usr/bin/env node
/** Reproduce the complete explicitly PD map subset from a pinned, CC0 institutional catalogue. */
import { readFile, writeFile, readdir, mkdir, access } from "node:fs/promises";
import { resolve, join, relative } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { fileURLToPath } from "node:url";
import {
  stanfordRecord,
  STANFORD_PROVIDER,
  STANFORD_REPOSITORY,
  STANFORD_REVISION,
} from "./stanford-records.mjs";
import { formatCatalogue } from "./catalogue-format.mjs";
import { LIVE_PROVIDERS } from "../src/worker/catalogue.js";
const exec = promisify(execFile);
const root = fileURLToPath(new URL("..", import.meta.url));
const args = process.argv.slice(2);
const arg = (name) =>
  args.includes(name) ? args[args.indexOf(name) + 1] : undefined;
const checkout = resolve(
  arg("--input") ?? join(root, ".cache/stanford-catalogue"),
);
const output = resolve(arg("--out") ?? join(root, "public/data"));
const offline = args.includes("--offline");
try {
  await access(join(checkout, ".git"));
} catch {
  if (offline)
    throw new Error(
      "No pinned metadata checkout. Run the online global harvest once, or supply --input.",
    );
  await mkdir(checkout, { recursive: true });
  await exec("git", ["init", checkout]);
  await exec("git", [
    "-C",
    checkout,
    "remote",
    "add",
    "origin",
    `${STANFORD_REPOSITORY}.git`,
  ]);
  await exec(
    "git",
    ["-C", checkout, "fetch", "--depth", "1", "origin", STANFORD_REVISION],
    { maxBuffer: 1024 * 1024 },
  );
  await exec("git", ["-C", checkout, "checkout", "--detach", "FETCH_HEAD"]);
}
const revision = (
  await exec("git", ["-C", checkout, "rev-parse", "HEAD"])
).stdout.trim();
if (revision !== STANFORD_REVISION)
  throw new Error(
    `Metadata revision mismatch: expected ${STANFORD_REVISION}, found ${revision}.`,
  );
const licence = await readFile(join(checkout, "LICENSE"), "utf8");
if (!licence.includes("CC0 1.0 Universal"))
  throw new Error("Metadata redistribution licence not established.");
async function* jsonFiles(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* jsonFiles(path);
    else if (entry.name.endsWith(".json")) yield path;
  }
}
let considered = 0;
const imported = [];
for await (const path of jsonFiles(join(checkout, "metadata-aardvark"))) {
  considered++;
  const record = stanfordRecord(
    JSON.parse(await readFile(path, "utf8")),
    relative(checkout, path).split("\\").join("/"),
  );
  if (record) imported.push(record);
}
if (!imported.length)
  throw new Error("No eligible records; leaving the last catalogue unchanged.");
const read = async (name) =>
  JSON.parse(await readFile(join(output, name), "utf8"));
const recordsDoc = await read("records.json");
const sourcesDoc = await read("sources.json");
const overlaysDoc = await read("overlays.json");
recordsDoc.records = [
  ...recordsDoc.records.filter((record) => record.providerId !== "stanford"),
  ...imported,
].sort(
  (a, b) =>
    (a.yearStart ?? Infinity) - (b.yearStart ?? Infinity) ||
    a.id.localeCompare(b.id),
);
recordsDoc.generatedAt = new Date().toISOString();
recordsDoc.method =
  "Primary institutional metadata: e-rara, swisstopo, Library of Congress, and the complete explicitly public-domain map subset of Stanford’s pinned CC0 catalogue. No geographic, decade or count quota is applied to Stanford.";
recordsDoc.selection["stanford:public-domain"] = {
  considered,
  kept: imported.length,
  sourceRevision: revision,
  metadataLicence: "CC0 1.0",
  rule: "All public Map-class records with explicit per-item PDM/CC0 image rights, original links and stated identity. No bbox or georeferencing requirement; conflicting/restricted rights are excluded.",
};
sourcesDoc.providers = [
  ...sourcesDoc.providers.filter((source) => source.id !== "stanford"),
  { ...STANFORD_PROVIDER, retrieved: recordsDoc.generatedAt.slice(0, 10) },
];
for (const source of LIVE_PROVIDERS) {
  const existing = sourcesDoc.providers.find((value) => value.id === source.id);
  if (existing) existing.liveSearch = source.api.catalogue;
  else
    sourcesDoc.providers.push({
      ...source,
      mode: "live-search",
      method:
        "Fetched on explicit user search. This registry entry does not claim any bundled records or completed live verification.",
    });
}
sourcesDoc.generatedAt = recordsDoc.generatedAt;
overlaysDoc.overlays = overlaysDoc.overlays.filter(
  (layer) => layer.providerId !== "stanford",
);
overlaysDoc.overlays.push(
  ...imported
    .filter((record) => record.georeference)
    .map((record) => ({
      id: `cog-${record.id.split(":")[1]}`,
      kind: "cog",
      providerId: "stanford",
      title: record.title,
      recordId: record.id,
      url: record.georeference.url,
      extent: record.extent,
      attribution: "Stanford University Libraries",
      license: record.rights,
      historical: true,
      timeValues: [],
      ...(record.depictedYearStart
        ? { mapYear: record.depictedYearStart }
        : {}),
    })),
);
formatCatalogue(recordsDoc, sourcesDoc, overlaysDoc);
await writeFile(
  join(output, "records.json"),
  JSON.stringify(recordsDoc) + "\n",
);
await writeFile(
  join(output, "sources.json"),
  JSON.stringify(sourcesDoc, null, 2) + "\n",
);
await writeFile(
  join(output, "overlays.json"),
  JSON.stringify(overlaysDoc, null, 2) + "\n",
);
console.log(
  `Imported ${imported.length} public-domain Stanford maps from ${considered} metadata records; ${imported.filter((record) => record.georeference).length} native COG overlays. Total: ${recordsDoc.records.length}.`,
);

import { rasterResponse } from './raster.js';
import { georeferenceResponse } from './georeference.js';
import { catalogueResponse } from './catalogue.js';
import { ALLOWLIST, USER_AGENT, VERSION, isAllowed } from './allowlist.js';
import { NOMINATIM_ATTRIBUTION, NOMINATIM_SOURCE, nominatimUrl, searchPayload } from './geocode.js';

/**
 * Request handler for the global historical maps Workers site.
 *
 * The Worker only answers `/api/*` (see `assets.run_worker_first` in
 * wrangler.jsonc); every other request is served directly from the static asset
 * directory `public/`.
 *
 * Why a proxy at all?
 *  - Worldwide place search runs on *OpenStreetMap's* Nominatim gazetteer. Its
 *    usage policy asks for an identified client, low request rates and caching;
 *    routing it through the Worker gives the project one identifiable
 *    User-Agent, a bounded query and a five-minute edge cache per query.
 *  - e-rara IIIF images/manifests normally allow CORS; `/api/fetch` is a
 *    *fallback* for clients/networks where the direct call fails. It is limited
 *    to a literal allowlist of hosts, so it cannot be used as an open proxy.
 *
 * No credentials are required or read by this Worker.
 */

function json(body, init = {}) {
  return new Response(JSON.stringify(body, null, 1), {
    ...init,
    headers: { 'content-type': 'application/json; charset=utf-8', ...(init.headers || {}) },
  });
}

async function upstream(url, { accept = '*/*', timeoutMs = 8000 } = {}) {
  return fetch(url, {
    headers: { 'user-agent': USER_AGENT, accept },
    signal: AbortSignal.timeout(timeoutMs),
    redirect: 'follow',
  });
}

/** Read a JSON file that ships with the site through the assets binding. */
async function asset(env, path, request) {
  const url = new URL(request.url);
  url.pathname = path;
  url.search = '';
  return env.ASSETS.fetch(new Request(url.toString(), { method: 'GET' }));
}

async function cachedJson(request, ctx, build, maxAge) {
  const cache = caches.default;
  const cacheKey = new Request(new URL(request.url).toString(), { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  const body = await build();
  const res = json(body, { headers: { 'cache-control': `public, max-age=${maxAge}` } });
  ctx.waitUntil(cache.put(cacheKey, res.clone()));
  return res;
}

/** GET /api/health — liveness plus the upstreams this Worker may contact. */
function health(request) {
  return json({
    ok: true,
    version: VERSION,
    runtime: 'cloudflare-workers',
    upstreams: ALLOWLIST.map((r) => r.host),
    endpoints: ['/api/health', '/api/records', '/api/layers', '/api/sources', '/api/search/places', '/api/fetch', '/api/raster', '/api/georeference', '/api/catalogue'],
    placeSearch: {
      primary: NOMINATIM_SOURCE,
      attribution: NOMINATIM_ATTRIBUTION,
      fallback: 'Local catalogue keyword search',
    },
    time: new Date().toISOString(),
  });
}

/** GET /api/search/places?q=&limit= — worldwide places. */
async function searchPlaces(request, ctx) {
  const url = new URL(request.url);
  const q = (url.searchParams.get('q') || '').trim();
  const limit = Math.min(Math.max(Number(url.searchParams.get('limit') || 8), 1), 10);
  if (q.length < 2 || q.length > 120) {
    return json({ error: 'query_too_short', detail: 'q must be 2..120 characters', results: [] }, { status: 400 });
  }
  return cachedJson(
    request,
    ctx,
    async () => {
      // 1) The worldwide gazetteer. One request per distinct, cached query.
      try {
        const res = await upstream(nominatimUrl(q, { limit }), { accept: 'application/json' });
        if (res.ok) {
          const payload = searchPayload(await res.json(), { limit, query: q });
          if (payload.results.length > 0) return payload;
        }
      } catch {
        // The client can still search the bundled catalogue by keyword.
      }
      return { results: [], query: q, source: NOMINATIM_SOURCE, attribution: NOMINATIM_ATTRIBUTION, note: 'Worldwide place search returned no usable result or is temporarily unavailable. Try a catalogue keyword instead.' };
    },
    300,
  );
}

/** GET /api/fetch?url= — allowlisted pass-through with a 1 h edge cache. */
async function fetchUpstream(request, ctx) {
  const url = new URL(request.url);
  const raw = url.searchParams.get('url');
  if (!raw) return json({ error: 'missing_url' }, { status: 400 });
  let target;
  try {
    target = new URL(raw);
  } catch {
    return json({ error: 'invalid_url' }, { status: 400 });
  }
  if (!isAllowed(target)) {
    return json({ error: 'host_not_allowed', host: target.hostname, allowlist: ALLOWLIST.map((r) => r.host) }, { status: 403 });
  }
  const cache = caches.default;
  const cacheKey = new Request(`${url.origin}/api/fetch?url=${encodeURIComponent(target.toString())}`, { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  let res;
  try {
    res = await upstream(target.toString(), { accept: url.searchParams.get('accept') || '*/*' });
  } catch (err) {
    return json({ error: 'upstream_unreachable', detail: String(err && err.message) }, { status: 502 });
  }
  if (!res.ok) return json({ error: 'upstream_error', status: res.status }, { status: 502 });
  const type = res.headers.get('content-type') || 'application/octet-stream';
  const out = new Response(res.body, {
    status: 200,
    headers: {
      'content-type': type,
      'cache-control': 'public, max-age=3600',
      'access-control-allow-origin': '*',
      'x-proxied-from': target.hostname,
    },
  });
  ctx.waitUntil(cache.put(cacheKey, out.clone()));
  return out;
}

export default {
  /**
   * @param {Request} request
   * @param {{ ASSETS: { fetch: (r: Request) => Promise<Response> } }} env
   * @param {{ waitUntil: (p: Promise<unknown>) => void }} ctx
   */
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname.startsWith('/api/')) {
      if (request.method !== 'GET' && request.method !== 'HEAD') {
        return json({ error: 'method_not_allowed' }, { status: 405, headers: { allow: 'GET, HEAD' } });
      }
      try {
        switch (url.pathname) {
          case '/api/health':
            return health(request);
          case '/api/search/places':
            return await searchPlaces(request, ctx);
          case '/api/raster':
            return await rasterResponse(request, ctx);
          case '/api/georeference':
            return await georeferenceResponse(request, env, ctx);
          case '/api/catalogue':
            return await catalogueResponse(request, ctx);
          case '/api/fetch':
            return await fetchUpstream(request, ctx);
          case '/api/records':
          case '/api/layers':
          case '/api/sources': {
            const path = { '/api/records': '/data/records.json', '/api/layers': '/data/overlays.json', '/api/sources': '/data/sources.json' }[
              url.pathname
            ];
            const res = await asset(env, path, request);
            if (!res.ok) return json({ error: 'asset_missing', path }, { status: 500 });
            return new Response(res.body, {
              status: 200,
              headers: {
                'content-type': 'application/json; charset=utf-8',
                'cache-control': 'public, max-age=300',
                'access-control-allow-origin': '*',
              },
            });
          }
          default:
            return json({ error: 'not_found', path: url.pathname }, { status: 404 });
        }
      } catch (err) {
        return json({ error: 'worker_error', detail: String(err && err.message) }, { status: 500 });
      }
    }

    // Defensive: if run_worker_first is widened, still behave like a static host.
    if (env && env.ASSETS) return env.ASSETS.fetch(request);
    return new Response('Not found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8' } });
  },
};

// NOTE: only `default` may be exported from a Workers entrypoint. workerd rejects
// non-function named exports at startup ("Incorrect type for map entry 'VERSION'"
// is the exact failure), so constants stay module-private and are exercised through
// the HTTP surface (see tests/worker.test.mjs → /api/health).

/** Bounded searches of original collection APIs. Never infer image rights from public access. */
import { USER_AGENT } from "./allowlist.js";
const SIZE = 12;
const first = (value) => (Array.isArray(value) ? value[0] : value);
const words = (value) =>
  Array.isArray(value)
    ? value
        .flat(Infinity)
        .filter((x) => typeof x === "string")
        .join(" ")
    : String(value ?? "");
const text = (value) =>
  words(value)
    .replace(/<[^>]*>/g, "")
    .trim();
const year = (value) =>
  Number(text(value).match(/\b(?:1[0-9]{3}|20[0-9]{2})\b/)?.[0]) || null;
function https(value, hosts) {
  try {
    const u = new URL(value);
    return u.protocol === "https:" &&
      hosts.includes(u.hostname) &&
      !u.port &&
      !u.username &&
      !u.password
      ? u.href
      : null;
  } catch {
    return null;
  }
}
export function openImageRights(value) {
  const statement = text(value);
  if (
    !statement ||
    /non[ -]?commercial|all rights reserved|permission (?:is )?required|not in the public domain|copyright undetermined|no known restrictions/i.test(
      statement,
    )
  )
    return null;
  if (
    /creativecommons\.org\/(?:publicdomain\/(?:mark|zero)\/1\.0|licenses\/by(?:-sa)?\/4\.0)/i.test(
      statement,
    ) ||
    /\b(?:is|are|in the|in) (?:the )?public domain\b/i.test(statement)
  )
    return statement;
  return null;
}
export function extentOf(value) {
  if (!value) return null;
  const west = Number(value.minX ?? value.west),
    east = Number(value.maxX ?? value.east),
    south = Number(value.minY ?? value.south),
    north = Number(value.maxY ?? value.north);
  return [west, east, south, north].every(Number.isFinite) &&
    west >= -180 &&
    east <= 180 &&
    south >= -90 &&
    north <= 90 &&
    west < east &&
    south < north
    ? { west, east, south, north }
    : null;
}
function recordBase({
  id,
  providerId,
  title,
  date,
  rights,
  recordUrl,
  thumbnail,
  institution,
  extent = null,
}) {
  const y = year(date);
  return {
    id,
    providerId,
    title: text(title),
    yearStart: y,
    yearEnd: y,
    depictedYearStart: null,
    depictedYearEnd: null,
    creators: [],
    rights,
    recordUrl,
    thumbnail,
    institution,
    type: "map",
    collection: `${institution} — live catalogue`,
    extent,
    geo: extent
      ? {
          lat: (extent.south + extent.north) / 2,
          lon: (extent.west + extent.east) / 2,
        }
      : null,
    geoNote:
      "Catalogue location is for discovery. No image alignment is inferred from a bounding box.",
    liveCatalogue: true,
  };
}
export function locRecord(data) {
  const d = data.item ?? data;
  const recordUrl = https(data.url ?? data.id ?? d.id, [
    "www.loc.gov",
    "loc.gov",
  ]);
  const id = recordUrl?.match(/\/item\/([^/]+)\//)?.[1];
  const rights = openImageRights([
    data.rights_advisory,
    d.rights_advisory,
    data.rights,
    d.rights,
    d.rights_information,
  ]);
  if (!id || !rights) return null;
  const image =
    (data.image_url ?? d.image_url ?? []).find((value) =>
      https(value, ["tile.loc.gov", "www.loc.gov"]),
    ) ?? null;
  const record = recordBase({
    id: `loc:${id}`,
    providerId: "loc",
    title: d.title ?? data.title,
    date: d.date ?? data.date,
    rights,
    recordUrl,
    thumbnail: image,
    institution: "Library of Congress",
  });
  const manifest = https(
    data.iiif_presentation_manifest ?? d.iiif_presentation_manifest,
    ["www.loc.gov"],
  );
  record.iiifManifest =
    manifest ?? `https://www.loc.gov/item/${id}/manifest.json`;
  record.creators = (d.contributor ?? d.creator ?? []).map?.(text) ?? [];
  record.subjectPlace = text(d.location ?? data.location);
  return record;
}
export function leventhalRecord(document) {
  const d = document.attributes ?? document;
  const rawId = text(document.id ?? d.id);
  if (!/^commonwealth:[a-z0-9]+$/.test(rawId)) return null;
  const rights = openImageRights([
    d.rights_ss,
    d.rights_statement_ss,
    d.license_ss,
    d.use_and_reproduction_ss,
    d.rights,
  ]);
  if (!rights) return null;
  const recordUrl = `https://collections.leventhalmap.org/search/${rawId}`;
  const record = recordBase({
    id: `leventhal:${rawId}`,
    providerId: "leventhal",
    title: first(
      d.title_info_primary_tsi ?? d.title_tsim ?? d.title_ssi ?? d.title,
    ),
    date: first(d.date_start_dtsi ?? d.date_tsim ?? d.date),
    rights,
    recordUrl,
    thumbnail: https(
      first(d.thumbnail_url_ss ?? d.thumbnail_url ?? d.thumbnail),
      ["collections.leventhalmap.org", "iiif.digitalcommonwealth.org"],
    ),
    institution: "Leventhal Map & Education Center / holding collection",
  });
  if (!record.title) return null;
  record.iiifManifest = `${recordUrl}/manifest`;
  return record;
}
export function usgsRecord(item) {
  const id = text(item.sourceId ?? item.id);
  if (!id || id.length > 120 || !item.title) return null;
  const source = https(item.metaUrl ?? item.metadataUrl ?? item.downloadURL, [
    "www.sciencebase.gov",
    "www.usgs.gov",
    "prd-tnm.s3.amazonaws.com",
    "ngmdb.usgs.gov",
  ]);
  if (!source) return null;
  const record = recordBase({
    id: `usgs:${id.replace(/[^a-zA-Z0-9._-]/g, "_")}`,
    providerId: "usgs",
    title: item.title,
    date: item.publicationDate,
    rights:
      "USGS-produced historical topographic map, public domain. Retain source credits.",
    recordUrl: source,
    thumbnail: https(item.previewGraphicURL ?? item.thumbnail, [
      "prd-tnm.s3.amazonaws.com",
      "ngmdb.usgs.gov",
      "www.sciencebase.gov",
    ]),
    institution: "U.S. Geological Survey",
    extent: extentOf(item.boundingBox),
  });
  record.downloads = Object.entries(item.urls ?? {})
    .map(([label, url]) => ({
      label,
      url: https(url, ["prd-tnm.s3.amazonaws.com", "ngmdb.usgs.gov"]),
    }))
    .filter((value) => value.url);
  if (
    item.downloadURL &&
    https(item.downloadURL, ["prd-tnm.s3.amazonaws.com", "ngmdb.usgs.gov"])
  )
    record.downloads.push({
      label: "Original map files",
      url: item.downloadURL,
    });
  record.geoNote =
    "The USGS Historical Topographic Map Collection supplies georeferenced products. The catalogue footprint is not used as an image transform; download the original product to inspect its georeferencing.";
  return record;
}
export const LIVE_PROVIDERS = [
  {
    id: "loc",
    name: "Library of Congress",
    homepage: "https://www.loc.gov/maps/",
    attribution: "Library of Congress / original holding collection",
    rights:
      "Only results carrying explicit compatible image-rights evidence are admitted.",
    api: { catalogue: "https://www.loc.gov/maps/?fo=json" },
  },
  {
    id: "leventhal",
    name: "Leventhal Map & Education Center",
    homepage: "https://collections.leventhalmap.org/",
    attribution:
      "Leventhal Map & Education Center at the Boston Public Library / original holding collection",
    rights:
      "Item-level public-domain or compatible licence required. Partner collections are checked separately.",
    api: { catalogue: "https://collections.leventhalmap.org/search.json" },
  },
  {

    extent: extentOf(item.boundingBox),
  });
  record.downloads = Object.entries(item.urls ?? {})
    .map(([label, url]) => ({
      label,
      url: https(url, ["prd-tnm.s3.amazonaws.com", "ngmdb.usgs.gov"]),
    }))
    .filter((value) => value.url);
  if (
    item.downloadURL &&
    https(item.downloadURL, ["prd-tnm.s3.amazonaws.com", "ngmdb.usgs.gov"])
  )
    record.downloads.push({
      label: "Original map files",
      url: item.downloadURL,
    });
  record.geoNote =
    "The USGS Historical Topographic Map Collection supplies georeferenced products. The catalogue footprint is not used as an image transform; download the original product to inspect its georeferencing.";
  return record;
}
export const LIVE_PROVIDERS = [
  {
    id: "loc",
    name: "Library of Congress",
    homepage: "https://www.loc.gov/maps/",
    attribution: "Library of Congress / original holding collection",
    rights:
      "Only results carrying explicit compatible image-rights evidence are admitted.",
    api: { catalogue: "https://www.loc.gov/maps/?fo=json" },
  },
  {
    id: "leventhal",
    name: "Leventhal Map & Education Center",
    homepage: "https://collections.leventhalmap.org/",
    attribution:
      "Leventhal Map & Education Center at the Boston Public Library / original holding collection",
    rights:
      "Item-level public-domain or compatible licence required. Partner collections are checked separately.",
    api: { catalogue: "https://collections.leventhalmap.org/search.json" },
  },
  {
    id: "usgs",
    name: "USGS Historical Topographic Maps",
    homepage: "https://ngmdb.usgs.gov/topoview/",
    attribution: "U.S. Geological Survey",
    rights:
      "USGS-produced historical topographic maps are public domain; retain source credits.",
    api: {
      catalogue: "https://tnmaccess.nationalmap.gov/api/v1/products",
      terms: "https://www.usgs.gov/faqs/are-usgs-topographic-maps-copyrighted",
    },
  },
];
async function get(url) {
  const response = await fetch(url, {
    headers: { accept: "application/json", "user-agent": USER_AGENT },
    signal: AbortSignal.timeout(12000),
  });
  if (!response.ok)
    throw new Error(`Collection returned HTTP ${response.status}`);
  const body = await response.text();
  if (body.length > 8 * 1024 * 1024)
    throw new Error("Collection response exceeds the catalogue limit");
  return JSON.parse(body);
}
export async function catalogueResponse(request, ctx) {
  const query = new URL(request.url).searchParams;
  const source = query.get("source"),
    q = (query.get("q") ?? "").trim();
  const page = Math.max(1, Math.min(10000, Number(query.get("page")) || 1));
  if (
    !LIVE_PROVIDERS.some((value) => value.id === source) ||
    q.length < 2 ||
    q.length > 160
  )
    return Response.json(
      { error: "source_and_query_required" },
      { status: 400 },
    );
  const key = new Request(request.url);
  const cached = await caches.default.match(key);
  if (cached) return cached;
  let documents = [],
    records = [],
    total = null;
  try {
    if (source === "loc") {
      const url = new URL("https://www.loc.gov/maps/");
      for (const [k, v] of Object.entries({
        fo: "json",
        q,
        c: String(SIZE),
        sp: String(page),
      }))
        url.searchParams.set(k, v);
      const data = await get(url.href);
      documents = (data.results ?? []).slice(0, SIZE);
      total = data.pagination?.total ?? null;
      // Rights advisories are often only present on an item's own record.
      for (let i = 0; i < documents.length; i += 3) {
        const chunk = await Promise.all(
          documents.slice(i, i + 3).map(async (document) => {
            const ready = locRecord(document);
            if (ready) return ready;
            const item = https(document.id ?? document.url, ["www.loc.gov"]);
            if (!item || !/^\/item\/[^/]+\/$/.test(new URL(item).pathname))
              return null;
            try {
              const url = new URL(item);
              url.searchParams.set("fo", "json");
              return locRecord(await get(url.href));
            } catch {
              return null;
            }
          }),
        );
        records.push(...chunk.filter(Boolean));
      }
    } else if (source === "leventhal") {
      const url = new URL("https://collections.leventhalmap.org/search.json");
      for (const [k, v] of Object.entries({
        q,
        per_page: String(SIZE),
        page: String(page),
      }))
        url.searchParams.set(k, v);
      const data = await get(url.href);
      documents = (data.response?.docs ?? data.data ?? []).slice(0, SIZE);
      total = data.response?.numFound ?? data.meta?.pages?.total_count ?? null;
      records = documents.map(leventhalRecord).filter(Boolean);
    } else {
      const url = new URL("https://tnmaccess.nationalmap.gov/api/v1/products");
      for (const [k, v] of Object.entries({
        datasets: "Historical Topographic Maps",
        max: String(SIZE),
        offset: String((page - 1) * SIZE),
        outputFormat: "JSON",
      }))
        url.searchParams.set(k, v);
      const bbox = (query.get("bbox") ?? "").split(",").map(Number);
      if (
        bbox.length === 4 &&
        bbox.every(Number.isFinite) &&
        bbox[0] < bbox[2] &&
        bbox[1] < bbox[3] &&
        bbox[0] >= -180 &&
        bbox[2] <= 180 &&
        bbox[1] >= -90 &&
        bbox[3] <= 90
      )
        url.searchParams.set("bbox", bbox.join(","));
      const data = await get(url.href);
      documents = (data.items ?? []).slice(0, SIZE);
      total = data.total ?? null;
      records = documents.map(usgsRecord).filter(Boolean);
    }
    for (const record of records) {
      const recordKey = new Request(
        `${new URL(request.url).origin}/api/catalogue-record?id=${encodeURIComponent(record.id)}`,
      );
      ctx.waitUntil(
        caches.default.put(
          recordKey,
          Response.json(record, {
            headers: { "cache-control": "public, max-age=86400" },
          }),
        ),
      );
    }
    const response = Response.json(
      {
        source,
        query: q,
        page,
        total,
        records,
        examined: documents.length,
        withheld: documents.length - records.length,
        nextPage: documents.length === SIZE ? page + 1 : null,
        note: "Only rights-cleared results are added. An unlocated or unaligned scan is still eligible; an unknown image-rights statement is not treated as permission.",
      },
      { headers: { "cache-control": "public, max-age=600" } },
    );
    ctx.waitUntil(caches.default.put(key, response.clone()));
    return response;
  } catch {
    return Response.json(
      {
        error: "collection_unavailable",
        source,
        records: [],
        note: "The original collection is temporarily unavailable. The bundled global catalogue remains usable.",
      },
      { status: 502 },
    );
  }
}
