/**
 * Detail panel: metadata, honest date statements, an interactive IIIF viewer
 * (region requests = real deep zoom), rights/credit and prominent links to the
 * holding institution.
 *
 * The viewer only uses documented IIIF Image API parameters (`regionByPx`,
 * `sizeByW`); every request URL is built by `iiif.js` and unit-tested there. When
 * a service refuses a region request the viewer falls back to the full-sheet
 * derivative and finally to the record thumbnail, always saying which state it is
 * in instead of showing an empty box.
 */

import { copyText, el, formatLanguage, formatYearRange, qs, setStatus, trapFocus } from './dom.js';
import { recordCenter } from './records.js';
import { fetchUpstreamJson } from './upstream.js';
import {
  boundsForCanvas,
  clampView,
  describeUpstreamError,
  eRaraViewerUrl,
  formatViewParam,
  fullImageUrl,
  imageRequestUrl,
  panView,
  parseManifest,
  parseViewParam,
  sheetOptionLabel,
  sheetThumbUrl,
  viewForCanvas,
  zoomPercent,
  zoomView,
} from './iiif.js';

const FULL_PREVIEW_WIDTH = 1000;
/** A work with more sheets than this gets the direct “jump to sheet” control. */
const JUMP_MIN_SHEETS = 12;

export function init(ctx) {
  const panel = qs('#detail');
  const body = qs('#detail-body');
  const scrim = qs('#scrim');
  if (!panel || !body) return;

  let opener = null;
  let current = null;
  let manifest = null;
  let page = 0;
  /** @type {ReturnType<typeof createViewer>|null} */
  let viewer = null;
  /** @type {IntersectionObserver|null} Loads sheet thumbnails that come into view. */
  let stripObserver = null;

  /** `source` records where the selection came from; the viewer behaves the same. */
  function open(record, { keepSheet = false } = {}) {
    if (!record) return;
    const changedWork = current?.id !== record.id;
    current = record;
    manifest = null;
    // A newly chosen work starts on its first sheet and on the whole sheet; an
    // explicitly shared `sh`/`vv` value (deep link or reload) is kept — `sh` is
    // clamped to the real canvas count once the manifest is parsed, `vv` to the
    // real sheet size once the image service states it.
    if (changedWork && !keepSheet) ctx.store.update({ sheet: 1, vv: '' });
    const wasOpen = !panel.hidden;
    if (!wasOpen) opener = document.activeElement;
    render(record);
    panel.hidden = false;
    if (scrim) scrim.hidden = false;
    panel.setAttribute('aria-modal', 'true');
    document.body.classList.add('has-detail');
    // Focus the heading only when the panel opens (not when its content is swapped).
    if (!wasOpen) body.querySelector('[data-detail-heading]')?.focus();
    // The viewer loads its manifest for every entry point, including `?sel=` links.
    loadManifest(record);
  }

  function close() {
    if (panel.hidden) return;
    viewer?.destroy();
    viewer = null;
    stripObserver?.disconnect();
    stripObserver = null;
    page = 0;
    // A closed panel must not leave a sheet number or a viewer region behind in
    // the shared URL.
    if (ctx.store.getState().sheet !== 1 || ctx.store.getState().vv) ctx.store.update({ sheet: 1, vv: '' });
    panel.hidden = true;
    if (scrim) scrim.hidden = true;
    panel.setAttribute('aria-modal', 'false');
    document.body.classList.remove('has-detail');
    current = null;
    body.replaceChildren();
    opener?.focus?.();
    opener = null;
    ctx.bus.emit('record:deselected', {});
  }

  const statusNode = () => qs('#detail-status');

  /* ------------------------------------------------------------ rendering */

  function render(record) {
    const center = recordCenter(record);
    // A previous viewer (the panel can switch records without closing) keeps a
    // window-resize and a fullscreen listener; drop it before the DOM is replaced.
    viewer?.destroy();
    viewer = null;
    const viewer_ = previewSection(record);
    body.replaceChildren(
      el('div', { class: 'app-detail__bar' }, [
        el('span', { class: 'zh-tag zh-tag--blue', text: 'Map details' }),
        el('button', {
          class: 'zh-button zh-button--small',
          type: 'button',
          text: 'Close (Esc)',
          onclick: close,
        }),
      ]),
      el('h2', { class: 'app-detail__title', id: 'detail-title', 'data-detail-heading': '', tabindex: '-1', text: record.title }),
      el('div', { class: 'app-detail__actions app-detail__actions--primary' }, [
        el('a', {
          class: 'zh-button',
          href: record.recordUrl,
          target: '_blank',
          rel: 'noopener',
          text: 'Open original record ↗',
        }),
        eRaraViewerUrl(record)
          ? el('a', {
              class: 'zh-button zh-button--ghost zh-button--small',
              href: eRaraViewerUrl(record),
              target: '_blank',
              rel: 'noopener',
              text: 'Open collection viewer ↗',
            })
          : null,
        el('button', {
          class: 'zh-button zh-button--ghost zh-button--small',
          type: 'button',
          text: 'Show on map',
          onclick: () => {
            const bounds = record.extent ?? (center ? { west: center.lon - 0.05, east: center.lon + 0.05, south: center.lat - 0.03, north: center.lat + 0.03 } : null);
            if (bounds) ctx.bus.emit('view:fit', { bounds });
            else setStatus(statusNode(), 'This record has no documented map extent.', 'info');
          },
        }),
      ]),
      viewer_,
      // Workflow actions sit under the preview (not above it): on a phone the
      // viewer used to start ~800 px down behind five stacked buttons.
      el('div', { class: 'app-detail__actions app-detail__actions--secondary' }, [
        pinButton(record),
        el('button', {
          class: 'zh-button zh-button--ghost zh-button--small',
          type: 'button',
          text: 'Filter to this map’s year',
          onclick: (event) => applyPeriod(record, event.currentTarget),
        }),
        el('button', {
          class: 'zh-button zh-button--ghost zh-button--small',
          type: 'button',
          text: 'Copy link',
          onclick: async (event) => {
            // The region reaches the URL debounced; flush it first so the copied
            // link is the view on screen even if the user clicks immediately.
            const region = viewer?.getViewParam?.();
            if (region !== undefined && region !== null) ctx.store.update({ vv: region });
            const ok = await copyText(window.location.href);
            event.currentTarget.textContent = ok ? 'Link copied ✓' : 'Could not copy';
            setTimeout(() => (event.currentTarget.textContent = 'Copy link'), 2500);
          },
        }),
        record.overlay
          ? overlayButton(record)
          : null,
      ]),
      reuseSection(record),
      factsSection(record),
      relatedSection(record),
      el('p', { class: 'visuallyhidden', role: 'status', 'aria-live': 'polite', id: 'detail-status' }),
      el('p', { class: 'zh-hint' }, [
        el('span', { text: 'Metadata is supplied by the holding collection. ' }),
        record.iiifManifest
          ? el('a', { href: record.iiifManifest, target: '_blank', rel: 'noopener', text: 'Open IIIF manifest (JSON) ↗' })
          : el('span', { text: 'No IIIF manifest available.' }),
      ]),
    );
    viewer = viewer_?.__viewer ?? null;
  }

  /* ------------------------------------------------- comparison pinning */

  const pinnedIds = () => String(ctx.store.getState().cmp || '').split(',').map((id) => id.trim()).filter(Boolean);

  function updatePinButton(button, record) {
    if (!button || !record) return;
    const pinned = pinnedIds().includes(record.id);
    button.textContent = pinned ? 'Saved ✓ (comparison)' : 'Save for comparison';
    button.setAttribute('aria-pressed', pinned ? 'true' : 'false');
  }

#!/usr/bin/env node
import { formatCatalogue } from './catalogue-format.mjs';
import { openImageRights } from '../src/worker/catalogue.js';
/**
 * Reproduce the seed dataset from primary sources.
 *
 * Sources (retrieved 2026-10-18):
 *  - e-rara OAI-PMH  https://www.e-rara.ch/oai  (set `zuz` = ZB Zürich, `landkarten`)
 *  - e-rara IIIF Presentation 2.0 manifests with verbatim metadata + stated map bbox
 *  - swisstopo WMTS capabilities https://wmts.geo.admin.ch/EPSG/3857/1.0.0/WMTSCapabilities.xml
 *
 * No upstream metadata is invented: titles/imprints/creators/institutions/rights are
 * copied from the IIIF manifest (which mirrors the catalogue record), and geographic
 * extents are parsed from the upstream "Kartendaten" statement. swisstopo overlay
 * editions come from the WMTS Time dimension.
 *
 * Usage:
 *   node scripts/fetch-records.mjs --out public/data      # refresh from the network
 *   node scripts/fetch-records.mjs --offline              # replay the .cache/ responses
 *   node scripts/fetch-records.mjs --out /tmp/out --no-write
 *
 * The script is deliberately dependency-free and polite: max 3 concurrent requests,
 * a short pause between manifest requests, a descriptive User-Agent, and an on-disk
 * response cache (`.cache/fetch/`, git-ignored) so repeated runs do not hammer the
 * upstreams. `--offline` never opens a network connection.
 */
import { addInternationalMaps } from './add-international-maps.mjs';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';

const UA = 'MeridianAtlas/1.0 (+https://github.com/igor-makarov/maps-n-stuff)';
const args = process.argv.slice(2);
const outDir = resolve(getArg('--out') || 'public/data');
const writeOutput = !args.includes('--no-write');
const OFFLINE = args.includes('--offline');
const RETRIEVED = '2026-10-19';
const CACHE_DIR = new URL('../.cache/fetch/', import.meta.url);

function getArg(name) {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : null;
}

function cacheFile(url, as) {
  const hash = createHash('sha1').update(url).digest('hex').slice(0, 20);
  return new URL(`./${hash}.${as === 'json' ? 'json' : 'txt'}`, CACHE_DIR);
}

async function get(url, { as = 'text', timeout = 25000, attempts = 3 } = {}) {
  const file = cacheFile(url, as);
  if (OFFLINE) {
    const cached = await readFile(file, 'utf8');
    return as === 'json' ? JSON.parse(cached) : cached;
  }
  for (let attempt = 1; ; attempt += 1) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeout);
    try {
      const res = await fetch(url, {
        headers: { 'user-agent': UA, accept: as === 'json' ? 'application/json' : '*/*' },
        signal: ctrl.signal,
      });
      if (!res.ok) {
        // e-rara's DOI landing pages throttle bursts (429) and sometimes answer 5xx;
        // a retry with backoff turns a transient outage into a slower fetch instead of
        // aborting the whole harvest (verify-endpoints.mjs has retried since 7-23).
        if ((res.status === 429 || res.status >= 500) && attempt < attempts) {
          await sleep(attempt * 1500);
          continue;
        }
        throw new Error(`${res.status} ${url}`);
      }
      const body = as === 'json' ? await res.json() : await res.text();
      await mkdir(CACHE_DIR, { recursive: true });
      await writeFile(file, as === 'json' ? JSON.stringify(body) : body);
      return body;
    } catch (err) {
      const transient =
        err.name !== 'AbortError' && !/^\d{3} /.test(err.message || '') && attempt < attempts;
      if (transient) {
        await sleep(attempt * 1500);
        continue;
      }
      throw err;
    } finally {
      clearTimeout(timer);
    }
  }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function decode(s) {
  return String(s || '')
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, num) => String.fromCodePoint(Number(num)))
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .trim();
}

function first(xml, tag) {
  const m = xml.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`));
  return m ? decode(m[1]) : null;
}

function all(xml, tag) {
  return [...xml.matchAll(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'g'))].map((m) => decode(m[1]));
}

/** e-rara OAI-PMH pages for one set; returns raw <record> strings. */
async function oaiRecords(set, maxPages) {
  const records = [];
  let token = null;
  for (let page = 0; page < maxPages; page++) {
    const url = token
      ? `https://www.e-rara.ch/oai?verb=ListRecords&resumptionToken=${encodeURIComponent(token)}`
      : `https://www.e-rara.ch/oai?verb=ListRecords&metadataPrefix=oai_dc&set=${encodeURIComponent(set)}`;
    const xml = await get(url);
    records.push(...all(xml, 'record'));
    const m = xml.match(/<resumptionToken[^>]*>([^<]+)<\/resumptionToken>/);
    token = m ? m[1] : null;
    if (!token) break;
    await sleep(120);
  }
  return records;
}

function parseOai(record) {
  const setSpecs = all(record, 'setSpec');
  const types = all(record, 'dc:type');
  const title = all(record, 'dc:title')[0] || '';
  const dates = all(record, 'dc:date');
  const ids = all(record, 'dc:identifier');
  const doi = ids.find((i) => i.startsWith('https://www.e-rara.ch/doi/')) || null;
  const oai = first(record, 'identifier');
  const titleId = (oai || '').split(':').pop();
  return {
    title,
    titles: all(record, 'dc:title'),
    dates,
    creators: all(record, 'dc:creator').filter(Boolean),
    publisher: first(record, 'dc:publisher'),
    contributors: all(record, 'dc:contributor'),
    description: all(record, 'dc:description'),
    format: first(record, 'dc:format'),
    rights: first(record, 'dc:rights'),
    doi,
    titleId,
    isMap: types.includes('Map'),
    zuz: setSpecs.includes('zuz'),
    year: parseYear(dates[0]),
  };
}

