#!/usr/bin/env node
/**
 * Reproduce the USGS Historical Topographic Map Collection (HTMC) tranche.
 *
 * Source: the documented TNM Access product API
 *   https://tnmaccess.nationalmap.gov/api/v1/products
 *   ?datasets=Historical%20Topographic%20Maps&outputFormat=JSON
 *
 * USGS-produced historical topographic maps are public domain.  The API states
 * each product's publication date, footprint, preview image and GeoPDF/GeoTIFF
 * files.  The footprint is kept as discovery metadata, never converted into an
 * image transform.  A native GeoTIFF is retained as evidence and as a download,
 * but this script does not claim that the browser renderer can display it.
 *
 * The API sorts its 186k products; requesting every row would make the static
 * catalogue file unusable.  The harvester therefore samples evenly spaced API
 * offsets and imports every eligible product from each sampled page.  The
 * offset plan and the resulting count are written to records.json, so the
 * tranche is reproducible and its coverage is explicit.  Run with a larger
 * --target to extend it, or --all to walk every API page (the latter is for a
 * sharded catalogue, not for this single-file asset).
 *
 * Usage:
 *   node scripts/harvest-usgs.mjs --target 3000
 *   node scripts/harvest-usgs.mjs --offline
 *   node scripts/harvest-usgs.mjs --all --target 200000
 *
 * Requests are cached under .cache/usgs/; retries are bounded and polite.
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { usgsRecord } from "../src/worker/catalogue.js";

const UA =
  "maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map explorer)";
const API = "https://tnmaccess.nationalmap.gov/api/v1/products";
const PAGE = 50;
const CACHE = new URL("../.cache/usgs/", import.meta.url);
const args = process.argv.slice(2);
const arg = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : fallback;
};
const target = Math.max(PAGE, Number(arg("--target", 3000)) || 3000);
const offline = args.includes("--offline");
const all = args.includes("--all");
const outDir = resolve(arg("--out", "public/data"));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const cacheFile = (offset) => {
  const hash = createHash("sha1").update(String(offset)).digest("hex").slice(0, 16);
  return new URL(`${offset}-${hash}.json`, CACHE);
};

async function getPage(offset, attempts = 4) {
  const file = cacheFile(offset);
  if (offline) {
    const body = await readFile(file, "utf8");
    return JSON.parse(body);
  }
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 75000);
    try {
      const url = new URL(API);
      for (const [key, value] of Object.entries({
        datasets: "Historical Topographic Maps",
        max: String(PAGE),
        offset: String(offset),
        outputFormat: "JSON",
      }))
        url.searchParams.set(key, value);
      const response = await fetch(url, {
        headers: { accept: "application/json", "user-agent": UA },
        signal: controller.signal,
      });
      if (!response.ok) {
        const transient =
          response.status === 429 || response.status >= 500;
        if (transient && attempt < attempts) {
          await sleep(attempt * 2500);
          continue;
        }
        throw new Error(`USGS TNM returned HTTP ${response.status}`);
      }
      const body = await response.json();
      if (!Array.isArray(body.items))
        throw new Error("USGS TNM response has no items array");
      await mkdir(CACHE, { recursive: true });
      await writeFile(file, JSON.stringify(body));
      return body;
    } catch (error) {
      lastError = error;
      if (attempt < attempts) {
        await sleep(attempt * 2500);
        continue;
      }
    } finally {
      clearTimeout(timer);
    }
  }
  throw new Error(`USGS TNM page ${offset} failed: ${lastError?.message || "unknown"}`);
}

/** Evenly spaced offsets so the alphabetical API ordering cannot bias one region. */
export function offsetPlan(total, wanted, page = PAGE) {
  if (!Number.isFinite(total) || total <= 0) return [];
  const count = Math.max(1, Math.ceil(wanted / page));
  const last = Math.max(0, total - page);
  const plan = new Set();
  for (let i = 0; i < count; i += 1) {
    const raw = count === 1 ? 0 : Math.round((i * last) / (count - 1));
    plan.add(Math.floor(raw / page) * page);
  }
  return [...plan].sort((a, b) => a - b);
}

/** A source record with an explicit public-domain statement, never inferred. */
export function buildUsgsRecord(item) {
  const record = usgsRecord(item);
  if (!record) return null;
  record.collection = "Historical Topographic Maps — USGS";
  record.institution = "U.S. Geological Survey";
  record.rights =
    "USGS-produced historical topographic map, public domain. Retain source credits.";
  record.languages = [];
  record.geoNote =
    "The USGS product footprint is shown for discovery. It is not used as an image transformation; the native GeoTIFF carries its own coordinate reference system.";
  const geotiff = record.downloads?.find(
    (entry) => entry.url && /\.tif(f)?$/i.test(new URL(entry.url).pathname),
  );
  if (geotiff) {
    record.georeference = {
      kind: "geotiff",
      url: geotiff.url,
      format: "GeoTIFF",
      attribution: "U.S. Geological Survey",
      note: "Native USGS GeoTIFF product. The file's internal CRS/georeferencing has not been converted into a browser overlay; use the download for GIS work.",
    };
  }
  return record;
}

export async function harvest({ wanted = target, walkAll = all } = {}) {
  const first = await getPage(0);
  const total = Number(first.total) || 0;
  if (!total) throw new Error("USGS TNM reported no products; keeping the catalogue unchanged.");
  const offsets = walkAll
    ? Array.from({ length: Math.ceil(total / PAGE) }, (_, i) => i * PAGE)
    : offsetPlan(total, wanted);
  const imported = new Map();
  let considered = 0;
  let pages = 0;
  for (let i = 0; i < offsets.length; i += 2) {
    const batch = offsets.slice(i, i + 2);
    const results = await Promise.all(batch.map((offset) => getPage(offset)));
    for (const result of results) {
      pages += 1;
      for (const item of result.items ?? []) {
        considered += 1;
        const record = buildUsgsRecord(item);
        if (record) imported.set(record.id, record);
      }
    }
    if (!offline) await sleep(180);
  }
  if (!imported.size)
    throw new Error("No eligible USGS records; keeping the catalogue unchanged.");
  return {
    records: [...imported.values()].sort(
      (a, b) =>
        (a.yearStart ?? Infinity) - (b.yearStart ?? Infinity) ||
        a.title.localeCompare(b.title, "en"),
    ),
    considered,
    total,
    offsets,
    pages,
  };
}

async function main() {
  const result = await harvest();
  const records = JSON.parse(await readFile(resolve(outDir, "records.json"), "utf8"));
  const sources = JSON.parse(await readFile(resolve(outDir, "sources.json"), "utf8"));
  const previous = records.records.filter((record) => record.providerId !== "usgs");
  records.records = [...previous, ...result.records].sort(
    (a, b) =>
      (a.yearStart ?? Infinity) - (b.yearStart ?? Infinity) ||
      a.title.localeCompare(b.title, "en") ||
      a.id.localeCompare(b.id),
  );
  records.generatedAt = new Date().toISOString();
  records.method =
    "Primary institutional metadata: e-rara, swisstopo, Library of Congress, Stanford's pinned CC0 catalogue and the public-domain USGS Historical Topographic Map Collection. No geographic or decade quota is applied within each imported provider tranche.";
  records.selection["usgs:htmc"] = {
    considered: result.considered,
    kept: result.records.length,
    apiTotal: result.total,
    sampledPages: result.pages,
    sampledOffsets: result.offsets,
    rule:
      "Every eligible product on evenly spaced TNM Access pages: a sourceId, title, publication year and valid footprint; preview and GeoPDF/GeoTIFF hosts are USGS/TNM. USGS-produced HTMC maps are public domain. The native GeoTIFF is recorded as evidence and download only; no browser overlay is claimed.",
  };
  const provider = {
    id: "usgs",
    name: "USGS Historical Topographic Maps",
    operator: "U.S. Geological Survey",
    homepage: "https://ngmdb.usgs.gov/topoview/",
    attribution: "U.S. Geological Survey",
    rights:
      "USGS-produced historical topographic maps are public domain; retain source credits.",
    terms: "https://www.usgs.gov/faqs/are-usgs-topographic-maps-copyrighted",
    api: {
      catalogue: "https://tnmaccess.nationalmap.gov/api/v1/products",
      documentation: "https://tnmaccess.nationalmap.gov/api/v1/docs",
    },
    mode: "imported+live-search",
    retrieved: new Date().toISOString().slice(0, 10),
    method:
      "Bulk metadata via TNM Access (datasets=Historical Topographic Maps), evenly spaced pages; titles, dates and footprints retained from the product API; preview URLs and native GeoPDF/GeoTIFF downloads retained.",
  };
  sources.providers = [...sources.providers.filter((source) => source.id !== "usgs"), provider];
  sources.generatedAt = records.generatedAt;
  await writeFile(resolve(outDir, "records.json"), JSON.stringify(records) + "\n");
  await writeFile(resolve(outDir, "sources.json"), JSON.stringify(sources, null, 2) + "\n");
  console.log(
    `USGS: ${result.records.length} maps from ${result.considered} products on ${result.pages} pages (${result.total} advertised); catalogue total ${records.records.length}.`,
  );
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  await main();
}
